import React, { useState, useEffect } from "react";

function MainMenu() {
    const [nextEvent, setNextEvent] = useState(null);
    const [timeLeft, setTimeLeft] = useState("");

    // 1. Fetch the next event from your API
    useEffect(() => {
        fetch("http://localhost:8000/api/events/upcoming")
            .then(res => res.json())
            .then(res => {
                const now = new Date();
                // Filter out junk dates (1899) and past events, then sort by start_date
                const upcoming = res.data
                    .filter(e => e.start_date && new Date(e.start_date) > now && new Date(e.start_date).getFullYear() > 1900)
                    .sort((a, b) => new Date(a.start_date) - new Date(b.start_date));

                if (upcoming.length > 0) setNextEvent(upcoming[0]);
            })
            .catch(err => console.error("Fetch error:", err));
    }, []);

    // 2. Countdown Timer Logic
    useEffect(() => {
        if (!nextEvent) return;

        const timer = setInterval(() => {
            const now = new Date().getTime();
            const target = new Date(nextEvent.start_date).getTime();
            const gap = target - now;

            if (gap < 0) {
                setTimeLeft("Started!");
                clearInterval(timer);
                return;
            }

            const d = Math.floor(gap / (1000 * 60 * 60 * 24));
            const h = Math.floor((gap % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
            const m = Math.floor((gap % (1000 * 60 * 60)) / (1000 * 60));
            const s = Math.floor((gap % (1000 * 60)) / 1000);

            setTimeLeft(`${d}d ${h}h ${m}m ${s}s`);
        }, 1000);

        return () => clearInterval(timer);
    }, [nextEvent]);

    const containerStyle = { display: "grid", gridTemplateColumns: "repeat(2, 1fr)", gap: 15, padding: "20px" };
    const itemStyle = { background: "white", padding: 25, borderRadius: 25, textDecoration: "none", color: "#2D3436", boxShadow: "0 4px 12px rgba(0,0,0,0.03)" };
    const countdownStyle = {
        gridColumn: "span 2",
        background: "linear-gradient(135deg, #A82324 0%, #721112 100%)",
        color: "white",
        padding: "30px",
        borderRadius: 25,
        textAlign: "center",
        boxShadow: "0 10px 20px rgba(168,35,36,0.2)"
    };

    return (
        <div style={containerStyle}>
            {/* Countdown Section */}
            <div style={countdownStyle}>
                {nextEvent ? (
                    <>
                        <div style={{ fontSize: "0.9rem", opacity: 0.8, marginBottom: 5 }}>NEXT EVENT</div>
                        <h2 style={{ margin: "5px 0", fontSize: "1.5rem" }}>{nextEvent.name || "Untitled Event"}</h2>
                        <div style={{ fontSize: "2rem", fontWeight: "800", margin: "15px 0", fontFamily: "monospace" }}>
                            {timeLeft}
                        </div>
                        <div style={{ fontSize: "0.85rem", opacity: 0.9 }}>
                            <span className="material-icons-round" style={{ fontSize: "1rem", verticalAlign: "middle", marginRight: 5 }}>place</span>
                            {nextEvent.venue_details || "Venue TBD"}
                        </div>
                    </>
                ) : (
                    <div>Loading next event...</div>
                )}
            </div>

            {/* Existing Menu Items */}
            {[
                { label: "Calendar", icon: "calendar_today" },
                { label: "Layout", icon: "grid_view" },
                { label: "Events", icon: "event" },
                { label: "Stats", icon: "insights" },
            ].map((item) => (
                <div key={item.label} style={itemStyle}>
                    <div style={{
                        width: 45, height: 45, borderRadius: 12, display: "flex",
                        alignItems: "center", justifyContent: "center", marginBottom: 15,
                        background: "rgba(168,35,36,0.1)", color: "#A82324"
                    }}>
                        <span className="material-icons-round">{item.icon}</span>
                    </div>
                    <div style={{ fontWeight: "600" }}>{item.label}</div>
                </div>
            ))}
        </div>
    );
}

export default MainMenu;
